import re


_PHONE_RE = re.compile(r'(?<!\d)(01[016789]-?\d{3,4}-?\d{4})(?!\d)')


def mask_phone(text):
    def _mask(match):
        phone = match.group(0)
        digits = phone.replace('-', '')
        if len(digits) != 11:
            return phone
        masked = digits[:3] + '****' + digits[7:]
        if '-' in phone:
            return masked[:3] + '-' + masked[3:7] + '-' + masked[7:]
        return masked

    return _PHONE_RE.sub(_mask, text)

